    // 설정 화면에서 NEW 배지로 알려주고 한 번에 덧붙인다.
    const CSP_INSTRUCTION_UPDATES = [
        {
            target: 'gemini',
            name: 'NSFW Scene Analysis',
            note: '성적인 장면일 때의 태그·의상 규칙',
            has: (text) => /\[\s*NSFW[^\]]*\]/i.test(text),
            build: () => '[NSFW Scene Analysis]\n' + getNsfwSceneAnalysisGuide()
        }
    ];

    function getMissingInstructionUpdates(text, target) {
        const body = String(text || '');
        return CSP_INSTRUCTION_UPDATES.filter(item => item.target === target && !item.has(body));
    }

    function appendMissingInstructionUpdates(text, target) {
        const missing = getMissingInstructionUpdates(text, target);
        if (!missing.length) return { text: String(text || ''), applied: [] };
        const merged = String(text || '').trimEnd() + '\n\n' + missing.map(item => item.build()).join('\n\n');
        return { text: merged, applied: missing.map(item => item.name) };
    }

    // 지침 textarea 옆 NEW 배지 상태를 현재 입력값 기준으로 다시 그린다.
    function refreshInstructionUpdateBadge(root, target) {
        const badge = root?.querySelector?.(`[data-csp-update-badge="${target}"]`);
        if (!badge) return;
        const textarea = root.querySelector(target === 'gemini' ? '#csp-gemini-instruction' : '#csp-nai-prompt-guide');
        const missing = getMissingInstructionUpdates(textarea?.value || '', target);
        if (!missing.length) {
            badge.hidden = true;
            return;
        }
        badge.hidden = false;
        badge.textContent = missing.length > 1 ? `NEW ${missing.length}` : 'NEW';
        badge.title = '눌러서 추가: ' + missing.map(item => `${item.name} (${item.note})`).join(' / ');
    }

